// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/// The DAO (2016), its vulnerable core rebuilt in modern Solidity.
/// The original lost about 3.6M ETH to the bug in splitDAO below.
contract TheDAO {
    string public constant name = "The DAO";

    error NoEtherSent();
    error BalanceTooLow();
    error NothingToSplit();
    error PayoutFailed();
    error OnlyCurator();
    error Reentrancy();

    uint256 private constant STRIPES = 16;

    mapping(address => uint256) public balances;
    mapping(address => uint256) public paidOut;
    // Sharded counters: each sender writes its own stripe, so unrelated
    // transactions no longer serialise on one shared slot. totalSupply can
    // both grow and shrink, so its stripes are signed deltas.
    mapping(uint256 => int256) private _totalSupplyStripe;
    mapping(uint256 => uint256) private _totalRewardsStripe;
    address public curator;

    uint256 private _locked = 1;

    event Transfer(address indexed from, address indexed to, uint256 amount);
    event Split(address indexed member, uint256 amount);
    event CuratorChanged(address indexed previousCurator, address indexed newCurator);

    modifier nonReentrant() {
        if (_locked != 1) revert Reentrancy();
        _locked = 2;
        _;
        _locked = 1;
    }

    constructor() {
        curator = msg.sender;
    }

    function totalSupply() public view returns (uint256 total) {
        int256 sum;
        for (uint256 i = 0; i < STRIPES; ++i) {
            sum += _totalSupplyStripe[i];
        }
        total = uint256(sum);
    }

    function totalRewards() public view returns (uint256 total) {
        for (uint256 i = 0; i < STRIPES; ++i) {
            total += _totalRewardsStripe[i];
        }
    }

    function _stripe(address account) private pure returns (uint256) {
        return uint256(uint160(account)) % STRIPES;
    }

    /// Buy DAO tokens one to one with ether during the creation phase.
    function createTokenProxy(address tokenHolder) external payable returns (bool) {
        if (msg.value == 0) revert NoEtherSent();
        balances[tokenHolder] += msg.value;
        _totalSupplyStripe[_stripe(tokenHolder)] += int256(msg.value);
        emit Transfer(address(0), tokenHolder, msg.value);
        return true;
    }

    function transfer(address to, uint256 amount) external returns (bool) {
        uint256 fromBalance = balances[msg.sender];
        if (fromBalance < amount) revert BalanceTooLow();
        unchecked {
            balances[msg.sender] = fromBalance - amount;
        }
        balances[to] += amount;
        emit Transfer(msg.sender, to, amount);
        return true;
    }

    /// Profit paid into the DAO, shared across token holders.
    function receiveReward() external payable {
        _totalRewardsStripe[_stripe(msg.sender)] += msg.value;
    }

    /// Leave the DAO and take your share of the ether with you.
    function splitDAO() external nonReentrant returns (bool) {
        uint256 share = balances[msg.sender];
        if (share == 0) revert NothingToSplit();

        // Compute the reward owed while the member's balance is still intact,
        // then apply every state change before any external call.
        uint256 reward = _pendingReward(msg.sender);

        balances[msg.sender] = 0;
        _totalSupplyStripe[_stripe(msg.sender)] -= int256(share);
        if (reward != 0) {
            paidOut[msg.sender] += reward;
        }

        // Interactions last: a reentrant call now sees a zero balance and the
        // nonReentrant guard, so it cannot be paid twice.
        if (reward != 0 && !payOut(msg.sender, reward)) revert PayoutFailed();
        if (!payOut(msg.sender, share)) revert PayoutFailed();
        emit Split(msg.sender, share);
        return true;
    }

    function _pendingReward(address account) internal view returns (uint256) {
        uint256 supply = totalSupply();
        if (supply == 0) return 0;
        uint256 owed = (balances[account] * totalRewards()) / supply;
        uint256 already = paidOut[account];
        return owed > already ? owed - already : 0;
    }

    function payOut(address recipient, uint256 amount) internal returns (bool) {
        (bool ok, ) = recipient.call{value: amount}("");
        return ok;
    }

    /// The curator could change who controlled the DAO, checked by msg.sender.
    function changeCurator(address newCurator) external {
        if (msg.sender != curator) revert OnlyCurator();
        address previousCurator = curator;
        curator = newCurator;
        emit CuratorChanged(previousCurator, newCurator);
    }
}
